reload_re=r'async function reloadAll\(\)\{const \[pr,bk,py,tk,ex,cl,im,pf,ow\]=await Promise\.all\(\[.*?\]\);profiles=pr\.data\|\|\[\];banks=bk\.data\|\|\[\];payments=py\.data\|\|\[\];tasks=tk\.data\|\|\[\];exceptions=ex\.data\|\|\[\];closeTasks=cl\.data\|\|\[\];imprest=im\.data\|\|\[\];performance=pf\.data\|\|\[\];ownership=ow\.data\|\|\[\];renderAll\(\)\}'
reload_new='''async function reloadAll(){const [pr,bk,py,tk,ex,cl,im,pf,ow]=await Promise.all([sb.from("profiles").select("id,email,full_name,role").eq("active",true),sb.from("bank_liquidity").select("*").order("company"),sb.from("payments").select("*,bank_accounts(company,bank_name,account_name)").order("created_at",{ascending:false}),sb.from("tasks").select("*,owner:profiles!tasks_owner_id_fkey(full_name),reviewer:profiles!tasks_reviewer_id_fkey(full_name)").order("due_date",{ascending:false}).order("created_at",{ascending:false}),sb.from("exceptions").select("*,owner:profiles!exceptions_owner_id_fkey(full_name),leave_delegations(*,absent:profiles!leave_delegations_absent_user_id_fkey(full_name),substitute:profiles!leave_delegations_substitute_user_id_fkey(full_name))").order("created_at",{ascending:false}),sb.from("monthly_close_tasks").select("*,owner:profiles!monthly_close_tasks_owner_id_fkey(full_name)").order("due_date").order("code"),sb.from("imprest_funds").select("*,custodian:profiles!imprest_funds_custodian_id_fkey(full_name)").order("created_at",{ascending:false}),sb.rpc("get_finance_team_performance"),sb.from("ownership_matrix").select("*").order("sort_order")]);profiles=pr.data||[];banks=bk.data||[];payments=py.data||[];tasks=tk.data||[];exceptions=ex.data||[];closeTasks=cl.data||[];imprest=im.data||[];performance=pf.data||[];ownership=ow.data||[];renderAll()}'''
