new='''function renderDashboard(){const bal=banks.reduce((s,b)=>s+Number(b.balance||0),0),res=banks.reduce((s,b)=>s+Number(b.reserved_balance||0),0);kpiBalance.textContent=money(bal);kpiReserved.textContent=money(res);kpiAvailable.textContent=money(bal-res);kpiCfo.textContent=payments.filter(p=>p.supervisor_status==="موافق"&&p.cfo_status==="معلق").length;const overdue=tasks.filter(isTaskOverdue).filter(t=>t.status!=="مكتمل").length,justify=tasks.filter(taskJustificationRequired).length;dashboardAlerts.innerHTML=overdue||justify?`${displayText('متأخر الآن')}: <b>${overdue}</b> &nbsp; | &nbsp; ${displayText('تبريرات معلقة')}: <b>${justify}</b>`:displayText('لا توجد تنبيهات حالية.')}'''
