task_re=r'function renderTasks\(\)\{.*?\}\nfunction openTaskModal'
task_new=r'''function riyadhToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Riyadh',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function taskDeadline(t){if(!t.due_date)return null;return new Date(`${t.due_date}T${t.due_time||'23:59:59'}+03:00`)}
function isTaskOverdue(t){const d=taskDeadline(t);return !!d&&new Date()>d&&t.status!=="مكتمل"&&!t.completed_at}
function taskJustificationRequired(t){return (isTaskOverdue(t)||!!t.justification_requested_at)&&!String(t.delay_justification||'').trim()&&t.status!=="مكتمل"}
function taskActionHtml(t){const a=[],mine=t.owner_id===profile.id;if(mine&&t.opened_at&&t.status!=="مكتمل"){if(t.status!=="قيد التنفيذ")a.push(`<button class="btn" onclick="startTask('${t.id}')">${displayText('بدء')}</button>`);a.push(`<button class="btn success" onclick="completeTask('${t.id}')">${displayText('إكمال')}</button>`)}if(mine&&taskJustificationRequired(t))a.push(`<button class="btn danger" onclick="submitTaskJustification('${t.id}')">${displayText('إضافة تبرير')}</button>`);if(profile.role==="Supervisor"&&t.status!=="مكتمل"&&(isTaskOverdue(t)||t.opened_at))a.push(`<button class="btn danger" onclick="requestTaskJustification('${t.id}')">${displayText('طلب تبرير')}</button>`);return a.join(' ')||'—'}
function renderTasks(){const today=riyadhToday(),todayRows=tasks.filter(t=>t.due_date===today),done=todayRows.filter(t=>t.status==="مكتمل"||t.completed_at).length,over=todayRows.filter(isTaskOverdue).length,just=todayRows.filter(taskJustificationRequired).length;taskKpis.innerHTML=`<div class="card"><span class="muted">${displayText('مهام اليوم')}</span><b>${todayRows.length}</b></div><div class="card"><span class="muted">${displayText('مكتمل اليوم')}</span><b>${done}</b></div><div class="card"><span class="muted">${displayText('متأخر الآن')}</span><b>${over}</b></div><div class="card"><span class="muted">${displayText('تبريرات معلقة')}</span><b>${just}</b></div>`;tasksBody.innerHTML=tasks.map(t=>{const note=taskJustificationRequired(t)?displayText('تبرير مطلوب'):(t.delay_justification||t.justification_request_note||'—');return `<tr class="${isTaskOverdue(t)?'task-overdue':''}"><td>${esc(t.name)}</td><td>${esc(t.owner?.full_name||"—")}</td><td>${esc(t.reviewer?.full_name||"—")}</td><td>${esc(t.due_date||"—")}</td><td>${esc(t.due_time?String(t.due_time).slice(0,5):"—")}</td><td>${badge(t.priority||"عادي")}</td><td>${badge(t.status||"لم يبدأ")}${t.opened_at&&t.status==="لم يبدأ"?` ${badge('مفتوحة')}`:''}</td><td class="task-control-note">${esc(note)}</td><td>${taskActionHtml(t)}</td></tr>`}).join("")||`<tr><td colspan="9" class="muted">—</td></tr>`}
function openDailyPlan(){if(profile.role!=="Supervisor")return;const today=riyadhToday(),rows=tasks.filter(t=>t.frequency==='يومي'&&t.due_date===today&&t.status!=="مكتمل");if(!rows.length){alert(currentLang==='en'?'No daily tasks are available for today.':'لا توجد مهام يومية متاحة لليوم.');return}const html=rows.map(t=>`<tr><td><input type="checkbox" class="plan-check" data-id="${t.id}" checked></td><td>${esc(t.owner?.full_name||'—')}</td><td style="white-space:normal">${esc(t.name)}</td><td>${badge(t.priority||'عادي')}</td><td><input type="time" class="plan-time" data-id="${t.id}" value="${t.due_time?String(t.due_time).slice(0,5):''}"></td></tr>`).join('');showModal(displayText('خطة اليوم / فتح المهام'),`<div class="note" style="margin-bottom:10px">${currentLang==='en'?'Select the tasks to release and set a due time for each selected task.':'حدد المهام التي سيتم فتحها اليوم وضع موعد الاستحقاق لكل مهمة قبل توجيه الفريق.'}</div><div class="table-wrap"><table class="plan-table"><thead><tr><th>✓</th><th>${displayText('المسؤول')}</th><th>${displayText('المهمة')}</th><th>${displayText('الأولوية')}</th><th>${displayText('الوقت')}</th></tr></thead><tbody>${html}</tbody></table></div><div class="row" style="margin-top:14px"><button class="btn success" onclick="saveDailyPlan()">${currentLang==='en'?'Release selected tasks':'فتح المهام المحددة'}</button></div>`)}
async function saveDailyPlan(){const items=[];document.querySelectorAll('.plan-check:checked').forEach(c=>{const id=c.dataset.id,time=document.querySelector(`.plan-time[data-id="${id}"]`)?.value||'';items.push({id,due_time:time})});if(!items.length)return alert(currentLang==='en'?'Select at least one task.':'حدد مهمة واحدة على الأقل.');if(items.some(x=>!x.due_time))return alert(currentLang==='en'?'Due time is required for every selected task.':'يجب تحديد وقت الاستحقاق لكل مهمة محددة.');const {data,error}=await sb.rpc('supervisor_open_daily_plan',{p_items:items});if(error)return alert(error.message);closeModal();await reloadAll();alert(currentLang==='en'?`${data} tasks released.`:`تم فتح ${data} مهمة وتوجيهها للفريق.`)}
async function startTask(id){const {error}=await sb.rpc('start_finance_task',{p_task_id:id});if(error)return alert(error.message);await reloadAll()}
async function submitTaskJustification(id){const text=prompt(currentLang==='en'?'Enter the required justification:':'اكتب التبرير المطلوب للتأخير أو التعثر:');if(!text||!text.trim())return;const {error}=await sb.rpc('submit_task_justification',{p_task_id:id,p_justification:text.trim()});if(error)return alert(error.message);await reloadAll()}
async function requestTaskJustification(id){const note=prompt(currentLang==='en'?'Reason/note for requesting justification (optional):':'سبب أو ملاحظة طلب التبرير (اختياري):')||'';const {error}=await sb.rpc('request_task_justification',{p_task_id:id,p_note:note});if(error)return alert(error.message);await reloadAll()}
async function completeTask(id){let justification=null;const t=tasks.find(x=>x.id===id);if(t&&taskJustificationRequired(t)){justification=prompt(currentLang==='en'?'This task is overdue or has a justification request. Enter justification before completion:':'هذه المهمة متأخرة أو عليها طلب تبرير. يجب إدخال التبرير قبل الإكمال:');if(!justification||!justification.trim())return}let {error}=await sb.rpc('complete_finance_task',{p_task_id:id,p_justification:justification});if(error&&String(error.message||'').includes('DELAY_JUSTIFICATION_REQUIRED')){justification=prompt(currentLang==='en'?'Justification is mandatory before completion:':'التبرير إلزامي قبل إكمال المهمة:');if(!justification||!justification.trim())return;({error}=await sb.rpc('complete_finance_task',{p_task_id:id,p_justification:justification.trim()}))}if(error)return alert(error.message);await reloadAll()}
function openTaskModal'''
